-- Change history: the ship's log in Anvil as it was read before a change record carried its tenant, through the sector's live missions, ships and refits; no route issues it, it is kept to read beside h1.
SELECT e.TableName, e.RowId, e.Sequence, e.EventTime, e.EventSource, e.ChangeSet FROM DataChangeEvents e WHERE (e.TableName = 'Missions' AND e.RowId IN (SELECT m.Id FROM Missions m WHERE m.SectorId = 'a1111111-1111-4111-8111-111111111111')) OR (e.TableName = 'Ships' AND e.RowId IN (SELECT s.Id FROM Ships s JOIN Hangars h ON h.Id = s.HangarId WHERE h.SectorId = 'a1111111-1111-4111-8111-111111111111')) OR (e.TableName = 'Refits' AND e.RowId IN (SELECT r.Id FROM Refits r JOIN Ships s ON s.Id = r.ShipId JOIN Hangars h ON h.Id = s.HangarId WHERE h.SectorId = 'a1111111-1111-4111-8111-111111111111')) ORDER BY e.EventTime DESC, e.TableName, e.RowId, e.Sequence DESC LIMIT 200
